output_text:
[
  {
    "id": "use_entry_cart",
    "text": "Shoppers are obliged to take the available entry cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "entry_cart_pickup": {
          "pre": {
            "and": [
              "at_entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "entry_cart_pickup"
    }
  },
  {
    "id": "no_hand_carrying_goods",
    "text": "Shoppers are prohibited from carrying merchandise by hand rather than using a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "using_cart": "hasCart"
      },
      "events": {
        "hand_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "using_cart"
              }
            ]
          },
          "post": "carrying_item_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "A shopper may pick up shelf items only while currently holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "return_cart_to_service_bay",
    "text": "Before leaving the store, shoppers are obliged to park their cart at the upper-left service bay.",
    "abstraction": {
      "state_properties": {
        "upper_left_service_bay": "at(0,1)",
        "cart_parked_at_service_bay": "cartAt(0,1)",
        "with_cart": "hasCart"
      },
      "events": {
        "service_bay_cart_drop": {
          "pre": {
            "and": [
              "upper_left_service_bay",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_service_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "service_bay_cart_drop"
    }
  },
  {
    "id": "depart_service_bay_on_foot",
    "text": "After parking a cart at the upper-left service bay, the shopper is obliged to leave that bay southward without the cart.",
    "abstraction": {
      "state_properties": {
        "upper_left_service_bay": "at(0,1)",
        "cart_parked_at_service_bay": "cartAt(0,1)",
        "with_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "service_bay_cart_drop": {
          "pre": {
            "and": [
              "upper_left_service_bay",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_service_bay"
        },
        "southward_departure_without_cart": {
          "pre": {
            "and": [
              "upper_left_service_bay",
              "without_cart",
              "S"
            ]
          },
          "post": "at(0,2)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "service_bay_cart_drop",
      "discharge": "southward_departure_without_cart"
    }
  },
  {
    "id": "do_not_retake_parked_service_cart",
    "text": "Once a cart is parked at the upper-left service bay, shoppers are prohibited from picking it up again.",
    "abstraction": {
      "state_properties": {
        "upper_left_service_bay": "at(0,1)",
        "cart_parked_at_service_bay": "cartAt(0,1)"
      },
      "events": {
        "retake_service_cart": {
          "pre": {
            "and": [
              "upper_left_service_bay",
              "cart_parked_at_service_bay",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "retake_service_cart"
    }
  },
  {
    "id": "exit_without_cart",
    "text": "Shoppers are prohibited from exiting the store while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "at_exit_door": "at(9,5)",
        "with_cart": "hasCart"
      },
      "events": {
        "cart_exit": {
          "pre": {
            "and": [
              "at_exit_door",
              "with_cart",
              "EXIT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_exit"
    }
  },
  {
    "id": "leave_cart_only_at_service_bay",
    "text": "A shopper may put down a cart only at the designated upper-left service bay.",
    "abstraction": {
      "state_properties": {
        "upper_left_service_bay": "at(0,1)",
        "not_at_service_bay": {
          "not": "at(0,1)"
        },
        "with_cart": "hasCart"
      },
      "events": {
        "cart_left_outside_service_bay": {
          "pre": {
            "and": [
              "with_cart",
              "LEAVE_CART",
              "not_at_service_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_left_outside_service_bay"
    }
  }
]
